25	  startListening(
26	    engine: Engine,
27	    options: ResizeSetupOptions | number = 250,
28	  ): void {
29	    if (this._disposed || this._boundHandler) return;
30	    const opts: ResizeSetupOptions =
31	      typeof options === "number" ? { debounceMs: options } : options;
32	    const delayMs = opts.debounceMs ?? 250;
33	    this._engine = engine;
34	    this._scrollDriver = opts.scrollDriver ?? null;
35	    this._debounce = new Debounce(delayMs);
36	    this._boundHandler = (): void => {
37	      this._debounce?.runDebounce(() => {
38	        const runtime = ResponsiveRuntime.getDefault();
39	        runtime.init();
40	        const snapshot = runtime.updateFromWindow();
41	        this._engine?.applyResponsiveSnapshot(snapshot);
42	        this._scrollDriver?.refresh?.();
