45	    const runtime = ResponsiveRuntime.getDefault();
46	    runtime.init();
47	    this._engine.applyResponsiveSnapshot(runtime.getSnapshot());
48	    window.addEventListener("resize", this._boundHandler);
49	    if (typeof window !== "undefined" && window.visualViewport != null) {
50	      this._visualViewportHandler = this._boundHandler;
51	      window.visualViewport.addEventListener("resize", this._visualViewportHandler);
52	    }
53	  }
54	
55	  register(engine: Engine, options: ResizeSetupOptions | number = 250): void {
56	    this.startListening(engine, options);
57	  }
58	
59	  dispose(): void {
